:root {
  color-scheme: light;
  --ink: #1c1917;
  --muted: #57534e;
  --line: #e7e5e4;
  --paper: #fafaf9;
  --card: #ffffff;
  --accent: #9a3412;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font: 16px/1.5 Georgia, "Iowan Old Style", Palatino, serif;
  color: var(--ink);
  background: var(--paper);
}

a {
  color: inherit;
}

.site-header {
  max-width: 42rem;
  margin: 0 auto;
  padding: 1.5rem 1rem 0;
}

.brand {
  font-weight: 700;
  text-decoration: none;
}

main {
  max-width: 42rem;
  margin: 0 auto;
  padding: 1rem 1rem 3rem;
  display: grid;
  gap: 1rem;
}

.panel {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 1rem 1.1rem 1.2rem;
}

h1,
h2 {
  font-size: 1.25rem;
  line-height: 1.3;
  margin: 0 0 0.8rem;
}

h2 {
  font-size: 1rem;
  margin-top: 1.2rem;
}

form {
  display: grid;
  gap: 0.75rem;
}

label {
  display: grid;
  gap: 0.25rem;
  color: var(--muted);
  font-size: 0.9rem;
}

input,
textarea,
button {
  font: inherit;
}

input,
textarea {
  width: 100%;
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 0.5rem 0.6rem;
  background: #fff;
}

button {
  justify-self: start;
  border: 0;
  border-radius: 6px;
  padding: 0.5rem 0.8rem;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
}

.book-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.6rem;
}

.book-card a {
  display: grid;
  gap: 0.1rem;
  text-decoration: none;
  padding: 0.55rem 0.2rem;
  border-bottom: 1px solid var(--line);
}

.book-title {
  font-weight: 700;
}

.book-author,
.empty,
.eyebrow,
.status {
  color: var(--muted);
}

.notes {
  white-space: pre-wrap;
}

.error {
  color: #9f1239;
  margin: 0;
}

