import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { createStore, splitByStatus } from "./lib/store.js";
import { bookPage, homePage, notFoundPage } from "./lib/html.js";

const root = path.dirname(fileURLToPath(import.meta.url));
const dataFile = process.env.BOOKS_FILE || path.join(root, "data", "books.json");
const port = Number(process.env.PORT || 3000);
const store = createStore(dataFile);

function send(res, status, body, type = "text/html; charset=utf-8") {
  res.writeHead(status, {
    "content-type": type,
    "content-length": Buffer.byteLength(body),
  });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(303, { location });
  res.end();
}

async function readForm(req) {
  const chunks = [];
  for await (const chunk of req) chunks.push(chunk);
  return new URLSearchParams(Buffer.concat(chunks).toString("utf8"));
}

async function handle(req, res) {
  const url = new URL(req.url || "/", `http://${req.headers.host || "localhost"}`);
  const pathname = url.pathname;

  if (req.method === "GET" && pathname === "/styles.css") {
    const css = await readFile(path.join(root, "public", "styles.css"));
    send(res, 200, css, "text/css; charset=utf-8");
    return;
  }

  if (req.method === "GET" && pathname === "/") {
    const lists = splitByStatus(await store.load());
    send(res, 200, homePage(lists));
    return;
  }

  if (req.method === "POST" && pathname === "/books") {
    const form = await readForm(req);
    const input = {
      title: form.get("title") ?? "",
      author: form.get("author") ?? "",
      notes: form.get("notes") ?? "",
    };
    try {
      const book = await store.add(input);
      redirect(res, `/books/${book.id}`);
    } catch (error) {
      const lists = splitByStatus(await store.load());
      send(
        res,
        400,
        homePage({
          ...lists,
          error: error.message,
          form: input,
        }),
      );
    }
    return;
  }

  const bookMatch = pathname.match(/^\/books\/([^/]+)$/);
  if (req.method === "GET" && bookMatch) {
    const book = await store.get(decodeURIComponent(bookMatch[1]));
    if (!book) {
      send(res, 404, notFoundPage());
      return;
    }
    send(res, 200, bookPage(book));
    return;
  }

  const finishMatch = pathname.match(/^\/books\/([^/]+)\/finish$/);
  if (req.method === "POST" && finishMatch) {
    const id = decodeURIComponent(finishMatch[1]);
    const book = await store.finish(id);
    if (!book) {
      send(res, 404, notFoundPage());
      return;
    }
    redirect(res, `/books/${book.id}`);
    return;
  }

  send(res, 404, notFoundPage());
}

export function startServer({ port: listenPort = port } = {}) {
  const server = createServer((req, res) => {
    handle(req, res).catch((error) => {
      console.error(error);
      if (!res.headersSent) send(res, 500, "Something went wrong.", "text/plain; charset=utf-8");
      else res.end();
    });
  });
  return new Promise((resolve) => {
    server.listen(listenPort, () => resolve(server));
  });
}

const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const server = await startServer();
  const address = server.address();
  console.log(`Reading list listening on http://localhost:${address.port}`);
}

