import { mkdtemp, readFile } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { describe, expect, it } from "vitest";
import {
  addBook,
  createStore,
  emptyLibrary,
  finishBook,
  parseLibrary,
  splitByStatus,
} from "./store.js";

describe("library helpers", () => {
  it("adds a reading book and lists it separately from finished books", () => {
    const { library, book } = addBook(emptyLibrary(), {
      title: " The Left Hand of Darkness ",
      author: " Ursula K. Le Guin ",
      notes: " Cold and kind. ",
    });

    expect(book.title).toBe("The Left Hand of Darkness");
    expect(book.author).toBe("Ursula K. Le Guin");
    expect(book.notes).toBe("Cold and kind.");
    expect(book.status).toBe("reading");
    expect(splitByStatus(library).reading).toEqual([book]);
    expect(splitByStatus(library).finished).toEqual([]);
  });

  it("marks a book finished without dropping the others", () => {
    const first = addBook(emptyLibrary(), { title: "One", author: "A" });
    const second = addBook(first.library, { title: "Two", author: "B" });
    const finished = finishBook(second.library, second.book.id);

    expect(finished.book.status).toBe("finished");
    expect(finished.book.finishedAt).toEqual(expect.any(String));
    expect(splitByStatus(finished.library)).toMatchObject({
      reading: [first.book],
      finished: [finished.book],
    });
    expect(finishBook(finished.library, "missing")).toBeNull();
  });

  it("rejects a library file that is not a book list", () => {
    expect(() => parseLibrary('{"nope":true}')).toThrow(/book list/);
  });
});

describe("json store", () => {
  it("keeps books after a new store reads the same file", async () => {
    const dir = await mkdtemp(path.join(os.tmpdir(), "books-"));
    const filePath = path.join(dir, "nested", "books.json");
    const store = createStore(filePath);

    const added = await store.add({
      title: "Piranesi",
      author: "Susanna Clarke",
      notes: "The house is bigger than it looks.",
    });
    const finished = await store.finish(added.id);
    const reloaded = createStore(filePath);

    expect(await reloaded.get(added.id)).toMatchObject({
      title: "Piranesi",
      status: "finished",
      notes: "The house is bigger than it looks.",
    });
    expect(finished.status).toBe("finished");
    const raw = JSON.parse(await readFile(filePath, "utf8"));
    expect(raw.books).toHaveLength(1);
  });
});

