{
  "name": "reading-list",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "dev": "node server.js",
    "build": "node --check server.js && node --check lib/store.js",
    "test": "vitest run"
  },
  "devDependencies": {
    "vitest": "^3.1.3"
  }
}

import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";

export const STATUSES = ["reading", "finished"];

export function emptyLibrary() {
  return { books: [] };
}

export function createBook({ title, author, notes }) {
  const book = {
    id: randomUUID(),
    title: String(title ?? "").trim(),
    author: String(author ?? "").trim(),
    notes: String(notes ?? "").trim(),
    status: "reading",
    createdAt: new Date().toISOString(),
    finishedAt: null,
  };
  if (!book.title) {
    throw new Error("Title is required.");
  }
  if (!book.author) {
    throw new Error("Author is required.");
  }
  return book;
}

export function addBook(library, input) {
  const book = createBook(input);
  return {
    library: { books: [book, ...library.books] },
    book,
  };
}

export function finishBook(library, id) {
  let found = null;
  const books = library.books.map((book) => {
    if (book.id !== id) return book;
    found = {
      ...book,
      status: "finished",
      finishedAt: book.finishedAt ?? new Date().toISOString(),
    };
    return found;
  });
  if (!found) return null;
  return { library: { books }, book: found };
}

export function findBook(library, id) {
  return library.books.find((book) => book.id === id) ?? null;
}

export function splitByStatus(library) {
  return {
    reading: library.books.filter((book) => book.status === "reading"),
    finished: library.books.filter((book) => book.status === "finished"),
  };
}

function isBook(value) {
  return (
    value &&
    typeof value === "object" &&
    typeof value.id === "string" &&
    typeof value.title === "string" &&
    typeof value.author === "string" &&
    typeof value.notes === "string" &&
    STATUSES.includes(value.status)
  );
}

export function parseLibrary(raw) {
  const data = JSON.parse(raw);
  if (!data || typeof data !== "object" || !Array.isArray(data.books)) {
    throw new Error("Library file is not a book list.");
  }
  if (!data.books.every(isBook)) {
    throw new Error("Library file contains an invalid book.");
  }
  return { books: data.books };
}

export function createStore(filePath) {
  async function load() {
    try {
      const raw = await readFile(filePath, "utf8");
      return parseLibrary(raw);
    } catch (error) {
      if (error && error.code === "ENOENT") return emptyLibrary();
      throw error;
    }
  }

  async function save(library) {
    await mkdir(path.dirname(filePath), { recursive: true });
    const tempPath = `${filePath}.tmp`;
    await writeFile(tempPath, `${JSON.stringify(library, null, 2)}\n`, "utf8");
    await rename(tempPath, filePath);
  }

  return {
    filePath,
    load,
    save,
    async add(input) {
      const current = await load();
      const next = addBook(current, input);
      await save(next.library);
      return next.book;
    },
    async finish(id) {
      const current = await load();
      const next = finishBook(current, id);
      if (!next) return null;
      await save(next.library);
      return next.book;
    },
    async get(id) {
      return findBook(await load(), id);
    },
  };
}

export function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

export function layout({ title, body }) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)}</title>
  <link rel="stylesheet" href="/styles.css">
</head>
<body>
  <header class="site-header">
    <a class="brand" href="/">Reading list</a>
  </header>
  <main>
    ${body}
  </main>
</body>
</html>
`;
}

function bookCard(book) {
  return `<li class="book-card">
    <a href="/books/${escapeHtml(book.id)}">
      <span class="book-title">${escapeHtml(book.title)}</span>
      <span class="book-author">${escapeHtml(book.author)}</span>
    </a>
  </li>`;
}

function bookList(books, emptyText) {
  if (books.length === 0) {
    return `<p class="empty">${escapeHtml(emptyText)}</p>`;
  }
  return `<ul class="book-list">${books.map(bookCard).join("")}</ul>`;
}

export function homePage({ reading, finished, error, form }) {
  const values = {
    title: form?.title ?? "",
    author: form?.author ?? "",
    notes: form?.notes ?? "",
  };
  const errorHtml = error ? `<p class="error" role="alert">${escapeHtml(error)}</p>` : "";
  return layout({
    title: "Reading list",
    body: `
      <section class="panel">
        <h1>Add a book</h1>
        ${errorHtml}
        <form method="post" action="/books">
          <label>
            Title
            <input name="title" required value="${escapeHtml(values.title)}">
          </label>
          <label>
            Author
            <input name="author" required value="${escapeHtml(values.author)}">
          </label>
          <label>
            Notes
            <textarea name="notes" rows="4">${escapeHtml(values.notes)}</textarea>
          </label>
          <button type="submit">Add book</button>
        </form>
      </section>
      <section class="panel">
        <h1>Currently reading</h1>
        ${bookList(reading, "Nothing in progress yet.")}
      </section>
      <section class="panel">
        <h1>Finished</h1>
        ${bookList(finished, "No finished books yet.")}
      </section>
    `,
  });
}

export function bookPage(book) {
  const notes = book.notes
    ? `<p class="notes">${escapeHtml(book.notes)}</p>`
    : `<p class="empty">No notes yet.</p>`;
  const finishForm =
    book.status === "reading"
      ? `<form method="post" action="/books/${escapeHtml(book.id)}/finish">
          <button type="submit">Mark as finished</button>
        </form>`
      : `<p class="status">Finished</p>`;
  return layout({
    title: book.title,
    body: `
      <article class="panel book-detail">
        <p class="eyebrow"><a href="/">All books</a></p>
        <h1>${escapeHtml(book.title)}</h1>
        <p class="book-author">${escapeHtml(book.author)}</p>
        ${finishForm}
        <h2>Notes</h2>
        ${notes}
      </article>
    `,
  });
}

export function notFoundPage() {
  return layout({
    title: "Not found",
    body: `
      <section class="panel">
        <h1>Book not found</h1>
        <p><a href="/">Back to the reading list</a></p>
      </section>
    `,
  });
}

:root {
