  --ink: #1c1917;
  --muted: #57534e;
  --line: #e7e5e4;
  --paper: #fafaf9;
  --card: #ffffff;
  --accent: #9a3412;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font: 16px/1.5 Georgia, "Iowan Old Style", Palatino, serif;
  color: var(--ink);
  background: var(--paper);
}

a {
  color: inherit;
}

.site-header {
  max-width: 42rem;
  margin: 0 auto;
  padding: 1.5rem 1rem 0;
}

.brand {
  font-weight: 700;
  text-decoration: none;
}

main {
  max-width: 42rem;
  margin: 0 auto;
  padding: 1rem 1rem 3rem;
  display: grid;
  gap: 1rem;
}

.panel {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 1rem 1.1rem 1.2rem;
}

