h2 {
  font-size: 1.25rem;
  line-height: 1.3;
  margin: 0 0 0.8rem;
}

h2 {
  font-size: 1rem;
  margin-top: 1.2rem;
}

form {
  display: grid;
  gap: 0.75rem;
}

label {
  display: grid;
  gap: 0.25rem;
  color: var(--muted);
  font-size: 0.9rem;
}

input,
textarea,
button {
  font: inherit;
}

input,
textarea {
  width: 100%;
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 0.5rem 0.6rem;
  background: #fff;
}

button {
  justify-self: start;
  border: 0;
  border-radius: 6px;
  padding: 0.5rem 0.8rem;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
}

.book-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.6rem;
