const home = await fetch(base + '/');
const homeHtml = await home.text();
if (!homeHtml.includes('Currently reading') || !homeHtml.includes('Finished') || !homeHtml.includes('Add a book')) {
  throw new Error('home missing sections');
}
const added = await fetch(base + '/books', {
  method: 'POST',
  headers: { 'content-type': 'application/x-www-form-urlencoded' },
  body: new URLSearchParams({ title: 'Kindred', author: 'Octavia E. Butler', notes: 'Time travel that does not flinch.' }),
  redirect: 'manual',
});
const location = added.headers.get('location');
if (added.status !== 303 || !location?.startsWith('/books/')) throw new Error('bad add redirect ' + added.status + ' ' + location);
const page = await fetch(base + location);
const pageHtml = await page.text();
for (const text of ['Kindred', 'Octavia E. Butler', 'Time travel that does not flinch.', 'Mark as finished']) {
  if (!pageHtml.includes(text)) throw new Error('detail missing ' + text);
}
const finished = await fetch(base + location + '/finish', { method: 'POST', redirect: 'manual' });
if (finished.status !== 303) throw new Error('finish status ' + finished.status);
const after = await fetch(base + '/');
const afterHtml = await after.text();
const reading = afterHtml.split('Finished')[0];
const done = afterHtml.split('Finished')[1];
if (reading.includes('Kindred')) throw new Error('still listed as reading');
if (!done.includes('Kindred')) throw new Error('not listed as finished');
const missing = await fetch(base + '/books/does-not-exist');
if (missing.status !== 404) throw new Error('expected 404');
console.log('ok', location);
"

